const UNICODE_SAMPLE: &str = "Příliš žluťoučký kůň úpěl ďábelské ódy.\n\
    Ελληνικά: Ξεσκεπάζω την ψυχοφθόρα βδελυγμία.\n\
    日本語: いろはにほへと ちりぬるを\n\
    עברית: דג סקרן שט בים מאוכזב\n\
    Emoji: 🦀🚀✨ — combining: e\u{301} a\u{308} vs é ä\n";

impl Fixture {
    /// Writes the whole tree below `root`, which must not exist yet.
    pub fn generate(root: &Path, scale: Scale) -> Result<Self, String> {
        encode::self_test()?;
        fs::create_dir_all(root.parent().unwrap_or(root))
            .map_err(|error| format!("cannot create {}: {error}", root.display()))?;
        fs::create_dir(root)
            .map_err(|error| format!("cannot create {}: {error}", root.display()))?;
        // The Windows scenarios' junctions; the check folder is gone before any item.
        #[cfg(windows)]
        junction_self_test(root)?;
        let mut fixture = Self {
            root: root.to_path_buf(),
            scale,
            items: Vec::new(),
        };
        let mut random = Random::new(SEED);
        fixture.text(&mut random)?;
        fixture.code()?;
        fixture.documents()?;
        fixture.images()?;
        fixture.archives(&mut random)?;
        fixture.sizes(&mut random)?;
        fixture.deep()?;
        fixture.many(&mut random)?;
        fixture.names()?;
        fixture.links()?;
        fixture.checksums(&mut random)?;
        fixture.viewer_extras()?;
        // Last: read-only entries would refuse the writes above.
        fixture.read_only()?;
        Ok(fixture)
    }

    pub fn path(&self, relative: &str) -> PathBuf {
        self.root.join(relative)
    }

    fn record(&mut self, path: &str, kind: &'static str, note: &'static str) {
        self.items.push(Item {
            path: path.to_owned(),
            kind,
            note,
        });
    }

    fn write(
        &mut self,
        path: &str,
        kind: &'static str,
        note: &'static str,
        data: &[u8],
    ) -> Result<(), String> {
        let full = self.root.join(path);
        if let Some(parent) = full.parent() {
            fs::create_dir_all(parent).map_err(|error| format!("{}: {error}", parent.display()))?;
        }
        fs::write(&full, data).map_err(|error| format!("{}: {error}", full.display()))?;
        self.record(path, kind, note);
        Ok(())
    }

    fn directory(&mut self, path: &str, note: &'static str) -> Result<(), String> {
        let full = self.root.join(path);
        fs::create_dir_all(&full).map_err(|error| format!("{}: {error}", full.display()))?;
        self.record(path, "folder", note);
        Ok(())
    }

    fn text(&mut self, random: &mut Random) -> Result<(), String> {
        self.directory("text", "text encodings and line shapes")?;
        let mut plain = String::new();
        for line in 0..200 {
            plain.push_str(&format!("{line:04} {}\n", sentence(random, 8)));
        }
        self.write(
            "text/plain.txt",
            "text",
            "ASCII, 200 lines",
            plain.as_bytes(),
        )?;
        self.write(
            "text/utf8.txt",
            "text",
            "UTF-8 multilingual",
            UNICODE_SAMPLE.as_bytes(),
        )?;
        let mut bom = vec![0xEF, 0xBB, 0xBF];
        bom.extend_from_slice(UNICODE_SAMPLE.as_bytes());
        self.write("text/utf8-bom.txt", "text", "UTF-8 with BOM", &bom)?;
        let mut le = vec![0xFF, 0xFE];
        let mut be = vec![0xFE, 0xFF];
        for unit in UNICODE_SAMPLE.encode_utf16() {
            le.extend_from_slice(&unit.to_le_bytes());
            be.extend_from_slice(&unit.to_be_bytes());
        }
        self.write("text/utf16le.txt", "text", "UTF-16 LE with BOM", &le)?;
        self.write("text/utf16be.txt", "text", "UTF-16 BE with BOM", &be)?;
        self.write(
            "text/crlf.txt",
            "text",
            "CRLF line endings",
            plain.replace('\n', "\r\n").as_bytes(),
        )?;
        let long: String = (0..200_000)
            .map(|index| (b'a' + (index % 26) as u8) as char)
            .collect();
        self.write(
            "text/long-line.txt",
            "text",
            "one 200,000-character line",
            long.as_bytes(),
        )?;
        let target = self.scale.huge_text_bytes();
        let mut huge = String::with_capacity(target + 128);
        let mut line = 0_u64;
        while huge.len() < target {
            huge.push_str(&format!(
                "2026-11-19T{:02}:{:02}:{:02}Z INFO line={line} {}\n",
                line / 3600 % 24,
                line / 60 % 60,
                line % 60,
                sentence(random, 10)
            ));
            line += 1;
        }
        self.write(
            "text/huge.log",
            "text",
            "large log (scale-dependent)",
            huge.as_bytes(),
        )?;
        self.write("text/empty.txt", "text", "zero bytes", b"")?;
        self.write(
            "text/no-final-newline.txt",
            "text",
            "no trailing newline",
            b"last line",
        )?;
        Ok(())
    }

    fn code(&mut self) -> Result<(), String> {
        self.directory("code", "source files with syntax")?;
        let files: [(&str, &str); 11] = [
            (
                "main.rs",
                "fn main() {\n    let answer: u32 = 42;\n    println!(\"{answer}\");\n}\n",
            ),
            (
                "script.py",
                "#!/usr/bin/env python3\n\ndef greet(name: str) -> str:\n    return f\"hello {name}\"\n",
            ),
            (
                "app.js",
                "export function sum(values) {\n  return values.reduce((a, b) => a + b, 0);\n}\n",
            ),
            (
                "style.css",
                "body {\n  color: #e0e0e0;\n  background: #101820;\n}\n",
            ),
            (
                "query.sql",
                "SELECT name, size FROM files WHERE size > 1024 ORDER BY name;\n",
            ),
            ("build.sh", "#!/bin/sh\nset -eu\necho \"building\"\n"),
            ("Makefile", "all:\n\t@echo done\n"),
            (
                "config.json",
                "{\n  \"theme\": \"dark\",\n  \"density\": [\"desktop\", \"touch\"]\n}\n",
            ),
            (
                "data.xml",
                "<?xml version=\"1.0\"?>\n<root><item id=\"1\">One</item></root>\n",
            ),
            ("settings.toml", "[window]\nwidth = 1340\nheight = 820\n"),
            (
                "notes.yaml",
                "fixture:\n  seeded: true\n  kinds: [text, image, archive]\n",
            ),
        ];
        for (name, content) in files {
            self.write(
                &format!("code/{name}"),
                "code",
                "source",
                content.as_bytes(),
            )?;
        }
        Ok(())
    }

    fn documents(&mut self) -> Result<(), String> {
        self.directory("docs", "Markdown, HTML and PDF")?;
        self.write(
            "docs/README.md",
            "markdown",
            "headings, lists, code",
            b"# Fixture README\n\nA *seeded* tree for **acceptance** runs.\n\n- one\n- two\n\n```rust\nfn main() {}\n```\n",
        )?;
        let mut guide = String::from("# Guide\n\n| Kind | Count |\n| --- | ---: |\n");
        for (index, word) in WORDS.iter().enumerate() {
            guide.push_str(&format!("| {word} | {index} |\n"));
        }
        guide.push_str("\n> Quote with [a link](https://example.invalid/) and `code`.\n");
        self.write(
            "docs/guide.md",
            "markdown",
            "table, quote, link",
            guide.as_bytes(),
        )?;
        // The HTML viewer serves assets below the page's folder only: the second image
        // climbs above it (`../`) and is denied by design (docs/developer/WEB_VIEWER_API.md).
        self.write(
            "docs/page.html",
            "html",
            "local stylesheet and image; a parent-relative image the viewer denies",
            b"<!doctype html><html><head><meta charset=\"utf-8\"><title>Fixture page</title>\
<link rel=\"stylesheet\" href=\"page_files/style.css\"></head><body><h1>Fixture page</h1>\
<p>Offline <b>HTML</b> with a local image:</p><img src=\"page_files/photo.png\" alt=\"photo\">\
<img src=\"../images/photo.png\" alt=\"outside\">\
<script>document.title = 'script ran';</script></body></html>\n",
        )?;
        self.write(
            "docs/page_files/style.css",
            "code",
            "stylesheet of page.html",
            b"h1 { color: #3a7bd5; }\n",
        )?;
        let photo = encode::png(160, 120, |x, y| {
            [
                (x * 255 / 159) as u8,
                (y * 255 / 119) as u8,
                ((x + y) % 256) as u8,
            ]
        });
        self.write(
            "docs/page_files/photo.png",
            "image",
            "image of page.html (160x120 RGB gradient)",
            &photo,
        )?;
        self.write("docs/plain.htm", "html", "minimal HTML", b"<p>plain</p>\n")?;
        self.write(
            "docs/report.pdf",
            "pdf",
            "one page, Helvetica",
            &encode::pdf(&["Midnight Explorer acceptance", "Seeded PDF fixture"]),
        )?;
        Ok(())
    }

    fn images(&mut self) -> Result<(), String> {
        self.directory("images", "generated raster and vector images")?;
        let photo = encode::png(160, 120, |x, y| {
            [
                (x * 255 / 159) as u8,
                (y * 255 / 119) as u8,
                ((x + y) % 256) as u8,
            ]
        });
        self.write("images/photo.png", "image", "160x120 RGB gradient", &photo)?;
        self.write(
            "images/banner.jpg",
            "image",
            "128x64 greyscale baseline JPEG",
            &encode::jpeg(16, 8, |bx, by| ((bx * 15 + by * 8) % 256) as u8),
        )?;
        let mut palette = [[0_u8; 3]; 256];
        for (index, colour) in palette.iter_mut().enumerate() {
            *colour = [index as u8, (255 - index) as u8, (index * 7 % 256) as u8];
        }
        self.write(
            "images/icon.gif",
            "image",
            "48x48 palette GIF",
            &encode::gif(48, 48, &palette, |x, y| ((x / 6 + y / 6) * 32 % 256) as u8),
        )?;
        self.write(
            "images/pattern.webp",
            "image",
            "64x64 lossless WebP checkerboard",
            &encode::webp(64, 64, [40, 60, 90], [230, 200, 120], |x, y| {
                (x / 8 + y / 8) % 2 == 0
            }),
        )?;
        self.write(
            "images/vector.svg",
            "image",
            "SVG shapes and text",
            b"<svg xmlns=\"http://www.w3.org/2000/svg\" width=\"120\" height=\"80\" viewBox=\"0 0 120 80\">\
<rect width=\"120\" height=\"80\" fill=\"#203040\"/><circle cx=\"40\" cy=\"40\" r=\"24\" fill=\"#3a7bd5\"/>\
<text x=\"70\" y=\"45\" fill=\"#fff\" font-size=\"14\">SVG</text></svg>\n",
        )?;
        let truncated = &photo[..photo.len() / 2];
        self.write(
            "images/truncated.png",
            "image",
            "corrupt: cut in half",
            truncated,
        )?;
        self.write(
            "images/zero.png",
            "image",
            "zero bytes with an image name",
            b"",
        )?;
        Ok(())
    }

    fn archives(&mut self, random: &mut Random) -> Result<(), String> {
        self.directory("archives", "zip, tar and tar.gz with nested folders")?;
        let members = vec![
            Member::directory("bundle"),
            Member::file("bundle/readme.txt", "Inside the bundle.\n"),
            Member::directory("bundle/nested"),
            Member::directory("bundle/nested/deeper"),
            Member::file("bundle/nested/deeper/data.bin", random.bytes(4096)),
            Member::file("bundle/nested/notes.md", "# Nested\n"),
            Member::file("bundle/ünïcödé 🦀.txt", "Unicode member name\n"),
            Member::directory("bundle/empty"),
        ];
        self.write(
            "archives/bundle.zip",
            "archive",
            "stored ZIP, nested folders",
            &encode::zip(&members),
        )?;
        let tar = encode::tar(&members);
        self.write(
            "archives/source.tar",
            "archive",
            "ustar, nested folders",
            &tar,
        )?;
        self.write(
            "archives/source.tar.gz",
            "archive",
            "gzip of source.tar",
            &encode::gzip(&tar),
        )?;
        let inner = encode::zip(&[Member::file("inner.txt", "Innermost.\n")]);
        let outer = encode::zip(&[
            Member::file("inner.zip", inner),
            Member::file("outer.txt", "Outer.\n"),
        ]);
        self.write(
            "archives/nested.zip",
            "archive",
            "ZIP containing a ZIP",
            &outer,
        )?;
        self.write(
            "archives/empty.zip",
            "archive",
            "ZIP with no members",
            &encode::zip(&[]),
        )?;
        self.write(
            "archives/not-a-zip.zip",
            "archive",
            "corrupt: text with a .zip name",
            b"plain text\n",
        )?;
        Ok(())
    }

    fn sizes(&mut self, random: &mut Random) -> Result<(), String> {
        self.directory("sizes", "empty, small and large binaries")?;
        self.write("sizes/zero.bin", "binary", "zero bytes", b"")?;
        self.write("sizes/one.bin", "binary", "one byte", &[0x5A])?;
        self.write(
            "sizes/block.bin",
            "binary",
            "4096 random bytes",
            &random.bytes(4096),
        )?;
        let huge = self.scale.huge_binary_bytes();
        let full = self.root.join("sizes/huge.bin");
        let mut file =
            fs::File::create(&full).map_err(|error| format!("{}: {error}", full.display()))?;
        let mut chunk_random = Random::new(SEED ^ 0xB16);
        let mut written = 0;
        while written < huge {
            let chunk = chunk_random.bytes((huge - written).min(1 << 20));
            file.write_all(&chunk)
                .map_err(|error| format!("{}: {error}", full.display()))?;
            written += chunk.len();
        }
        self.record(
            "sizes/huge.bin",
            "binary",
            "large random file (scale-dependent)",
        );
        Ok(())
    }

    fn deep(&mut self) -> Result<(), String> {
        self.directory("deep", "twelve nested levels, a file in each")?;
        let mut path = String::from("deep");
        for level in 1..=12 {
            path.push_str(&format!("/level-{level:02}"));
            fs::create_dir_all(self.root.join(&path)).map_err(|error| error.to_string())?;
            let file = format!("{path}/file-{level:02}.txt");
            fs::write(self.root.join(&file), format!("depth {level}\n"))
                .map_err(|error| error.to_string())?;
        }
        self.record("deep/level-01/…/level-12", "folder", "nested chain");
        Ok(())
    }

    fn many(&mut self, random: &mut Random) -> Result<(), String> {
        self.directory("many", "thousands of small files and ten folders")?;
        let count = self.scale.many_files();
        for index in 0..count {
            let extension = ["dat", "txt", "log", "bin"][index % 4];
            let length = random.below(256) as usize;
            let path = self.root.join(format!("many/item-{index:05}.{extension}"));
            fs::write(&path, random.bytes(length))
                .map_err(|error| format!("{}: {error}", path.display()))?;
        }
        for index in 0..10 {
            fs::create_dir(self.root.join(format!("many/group-{index:02}")))
                .map_err(|error| error.to_string())?;
        }
        self.record(
            "many/item-NNNNN.{dat,txt,log,bin}",
            "files",
            "count depends on scale",
        );
        Ok(())
    }

    fn names(&mut self) -> Result<(), String> {
        self.directory("names", "awkward and Unicode names")?;
        let long = format!("{}.txt", "long-name-".repeat(22));
        let names: Vec<String> = vec![
            "with spaces.txt".into(),
            "  leading spaces.txt".into(),
            "trailing space .txt".into(),
            ".hidden".into(),
            "-leading-dash.txt".into(),
            "Ünïcödé.txt".into(),
            "emoji 🦀🚀.txt".into(),
            "combining e\u{301}.txt".into(),
            "precomposed é.txt".into(),
            "日本語のファイル.txt".into(),
            "Ελληνικά.txt".into(),
            "עברית.txt".into(),
            "UPPER.TXT".into(),
            "lower.txt".into(),
            "#hash&amp;$dollar%percent.txt".into(),
            "semi;colon,comma=equals.txt".into(),
            "no-extension".into(),
            "multiple.dots.in.name.tar.gz.txt".into(),
            long,
        ];
        for name in &names {
            let path = self.root.join("names").join(name);
            fs::write(&path, name.as_bytes())
                .map_err(|error| format!("{}: {error}", path.display()))?;
        }
        fs::create_dir(self.root.join("names/.hidden-folder"))
            .map_err(|error| error.to_string())?;
        fs::write(
            self.root.join("names/.hidden-folder/inside.txt"),
            "hidden\n",
        )
        .map_err(|error| error.to_string())?;
        fs::create_dir(self.root.join("names/folder with spaces"))
            .map_err(|error| error.to_string())?;
        fs::write(self.root.join("names/folder with spaces/file.txt"), "x\n")
            .map_err(|error| error.to_string())?;
        self.record(
            "names/*",
            "files",
            "spaces, dots, dashes, Unicode, NFC/NFD, RTL, 220-byte name",
        );
        Ok(())
    }

    #[cfg(unix)]
    fn links(&mut self) -> Result<(), String> {
        use std::os::unix::fs::symlink;
        self.directory("links", "symbolic links")?;
        let links = [
            ("to-folder", "../deep/level-01", "link to a folder"),
            ("to-file", "../text/plain.txt", "link to a file"),
            ("dangling", "../does-not-exist", "dangling link"),
            ("to-self", ".", "link to its own folder (cycle)"),
        ];
        for (name, target, note) in links {
            let path = self.root.join("links").join(name);
            symlink(target, &path).map_err(|error| format!("{}: {error}", path.display()))?;
            self.record(&format!("links/{name}"), "link", note);
        }
        Ok(())
    }

    #[cfg(not(unix))]
    fn links(&mut self) -> Result<(), String> {
        // Windows symbolic links need a privilege this suite does not assume.
        self.directory("links", "empty: symbolic links are Unix-only here")
    }

    fn checksums(&mut self, random: &mut Random) -> Result<(), String> {
        self.directory(
            "checksums",
            "data files with SHA-256, MD5 and SFV manifests",
        )?;
        let files = [
            ("alpha.bin", random.bytes(10_000)),
            ("beta.bin", random.bytes(65_537)),
            ("gamma.txt", b"gamma checksum fixture\n".to_vec()),
            ("delta empty.txt", Vec::new()),
        ];
        let (mut sha, mut md5, mut sfv) =
            (String::new(), String::new(), String::from("; generated\n"));
        for (name, data) in &files {
            self.write(
                &format!("checksums/{name}"),
                "binary",
                "checksum input",
                data,
            )?;
            sha.push_str(&format!("{}  {name}\n", encode::hex(&encode::sha256(data))));
            md5.push_str(&format!("{}  {name}\n", encode::hex(&encode::md5(data))));
            sfv.push_str(&format!("{name} {:08X}\n", encode::crc32(data)));
        }
        self.write(
            "checksums/all.sha256",
            "manifest",
            "valid SHA-256 manifest",
            sha.as_bytes(),
        )?;
        self.write(
            "checksums/all.md5",
            "manifest",
            "valid MD5 manifest",
            md5.as_bytes(),
        )?;
        self.write(
            "checksums/all.sfv",
            "manifest",
            "valid SFV (CRC32)",
            sfv.as_bytes(),
        )?;
        let bad = sha.replacen(
            &encode::hex(&encode::sha256(&files[2].1)),
            &"0".repeat(64),
            1,
        );
        self.write(
            "checksums/mismatch.sha256",
            "manifest",
            "one wrong hash (gamma.txt)",
            bad.as_bytes(),
        )?;
        let missing = format!("{sha}{}  missing-file.bin\n", "1".repeat(64));
        self.write(
            "checksums/missing.sha256",
            "manifest",
            "names a missing file",
            missing.as_bytes(),
        )?;
        Ok(())
    }

    #[cfg(unix)]
    fn read_only(&mut self) -> Result<(), String> {
        use std::os::unix::fs::PermissionsExt;
        self.directory("readonly", "read-only file and folder")?;
        self.write("readonly/locked.txt", "text", "mode 0444", b"read only\n")?;
        self.write(
            "readonly/locked-folder/inside.txt",
            "text",
            "inside a mode 0555 folder",
            b"inside\n",
        )?;
        for (path, mode) in [
            ("readonly/locked.txt", 0o444),
            ("readonly/locked-folder", 0o555),
        ] {
            let full = self.root.join(path);
            fs::set_permissions(&full, fs::Permissions::from_mode(mode))
                .map_err(|error| format!("{}: {error}", full.display()))?;
        }
        Ok(())
    }

    #[cfg(not(unix))]
    fn read_only(&mut self) -> Result<(), String> {
        self.directory("readonly", "read-only file")?;
        self.write(
            "readonly/locked.txt",
            "text",
            "read-only attribute",
            b"read only\n",
        )?;
        let full = self.root.join("readonly/locked.txt");
        let mut permissions = fs::metadata(&full)
            .map_err(|error| error.to_string())?
            .permissions();
        permissions.set_readonly(true);
        fs::set_permissions(&full, permissions).map_err(|error| error.to_string())
    }

    /// Top-level folders, in name order: every scenario that visits "every fixture
    /// folder" walks these.
    pub fn top_folders(&self) -> Vec<String> {
        let mut folders: Vec<String> = fs::read_dir(&self.root)
            .into_iter()
            .flatten()
            .flatten()
            .filter(|entry| entry.file_type().is_ok_and(|kind| kind.is_dir()))
            .filter_map(|entry| entry.file_name().into_string().ok())
            .collect();
        folders.sort();
        folders
    }
}

fn sentence(random: &mut Random, words: usize) -> String {
    (0..words)
        .map(|_| WORDS[random.below(WORDS.len() as u64) as usize])
        .collect::<Vec<_>>()
        .join(" ")
}

/// Create a new folder `base` in `parent` (`base-2`, `base-3`, … when the name is
/// taken) and return it. Never returns a folder that existed before: the suite deletes
/// only what it created itself.
pub fn create_fresh(parent: &Path, base: &str) -> Result<PathBuf, String> {
    for attempt in 1..=99 {
        let path = if attempt == 1 {
            parent.join(base)
        } else {
            parent.join(format!("{base}-{attempt}"))
        };
        match fs::create_dir(&path) {
            Ok(()) => return Ok(path),
            Err(error) if error.kind() == std::io::ErrorKind::AlreadyExists => {}
            Err(error) => return Err(format!("cannot create {}: {error}", path.display())),
        }
    }
    Err(format!(
        "cannot create a new {base} folder in {}: 99 names are taken",
        parent.display()
    ))
}

/// Give the owner back what fixtures and scenarios took away below `path`, without
/// following links: every folder gets owner read, write and search permission, every
/// file owner write permission. A kept run folder (or a scenario's work folder) can
/// then always be deleted, in a file manager too. Returns the paths it could not change.
pub fn restore_owner_write(path: &Path) -> Vec<PathBuf> {
    let mut stuck = Vec::new();
    restore_into(path, &mut stuck);
    stuck
}

#[cfg(unix)]
fn restore_into(path: &Path, stuck: &mut Vec<PathBuf>) {
    use std::os::unix::fs::PermissionsExt;
    let Ok(metadata) = fs::symlink_metadata(path) else {
        return;
    };
    let wanted = if metadata.is_dir() {
        0o700
    } else if metadata.is_file() {
        0o200
    } else {
        // Links are never followed; other kinds carry no fixture permissions.
        return;
    };
    let mode = metadata.permissions().mode();
    if mode & wanted != wanted
        && fs::set_permissions(path, fs::Permissions::from_mode(mode | wanted)).is_err()
    {
        stuck.push(path.to_path_buf());
    }
    if metadata.is_dir() {
        for entry in fs::read_dir(path).into_iter().flatten().flatten() {
            restore_into(&entry.path(), stuck);
        }
    }
}

#[cfg(not(unix))]
fn restore_into(path: &Path, stuck: &mut Vec<PathBuf>) {
    let Ok(metadata) = fs::symlink_metadata(path) else {
        return;
    };
    if metadata.file_type().is_symlink() {
        return;
    }
    let mut permissions = metadata.permissions();
    if permissions.readonly() {
        #[allow(clippy::permissions_set_readonly_false)]
        permissions.set_readonly(false);
        if fs::set_permissions(path, permissions).is_err() {
            stuck.push(path.to_path_buf());
        }
    }
    // What `deny_read` and `deny_write` took away: this account's deny entries on a
    // folder that cannot be listed or refuses a new entry (here or in a staged child that
    // ended before it gave them back), and on the entries this process denied otherwise
    // (unreadable files, the entries of a write-protected folder). Files are not probed
    // one by one (work folders hold up to 100,000), and none of those entries keeps its
    // folder from being deleted once the folder is restored.
    let denied = denied_entries().contains(path)
        || (metadata.is_dir() && (read_denied(path, &metadata) || write_denied(path, &metadata)));
    if denied && allow_read(path).is_err() {
        stuck.push(path.to_path_buf());
    }
    if metadata.is_dir() {
        for entry in fs::read_dir(path).into_iter().flatten().flatten() {
            restore_into(&entry.path(), stuck);
        }
    }
}

#[cfg(not(unix))]
fn refused(result: std::io::Result<()>) -> bool {
    result.is_err_and(|error| error.kind() == std::io::ErrorKind::PermissionDenied)
}

/// Whether this account may not list the folder `path`: a deny entry of [`deny_read`]
/// is still there.
#[cfg(not(unix))]
fn read_denied(path: &Path, metadata: &fs::Metadata) -> bool {
    metadata.is_dir() && refused(fs::read_dir(path).map(drop))
}

/// The entries this process gave deny entries ([`deny_read`], [`deny_write`]) and has
/// not restored yet.
#[cfg(not(unix))]
fn denied_entries() -> std::sync::MutexGuard<'static, std::collections::BTreeSet<PathBuf>> {
    static DENIED: std::sync::Mutex<std::collections::BTreeSet<PathBuf>> =
        std::sync::Mutex::new(std::collections::BTreeSet::new());
    DENIED
        .lock()
        .unwrap_or_else(std::sync::PoisonError::into_inner)
}

/// Whether this account may not create an entry in the folder `path` (a deny entry of
/// [`deny_write`]): probed by creating and removing an empty folder with a reserved name.
#[cfg(not(unix))]
fn write_denied(path: &Path, metadata: &fs::Metadata) -> bool {
    if !metadata.is_dir() {
        return false;
    }
    let probe = path.join(".midnight-acceptance-write-probe");
    let created = fs::create_dir(&probe);
    if created.is_ok() {
        let _ = fs::remove_dir(&probe);
    }
    refused(created)
}

/// This account's security identifier (`S-1-…`), from `whoami`, for its own deny
/// entries: the suite takes access away from itself only.
#[cfg(windows)]
fn account_sid() -> Result<&'static str, String> {
    static SID: std::sync::OnceLock<Result<String, String>> = std::sync::OnceLock::new();
    SID.get_or_init(|| {
        let output = std::process::Command::new("whoami")
            .args(["/user", "/fo", "csv", "/nh"])
            .stdin(std::process::Stdio::null())
            .output()
            .map_err(|error| format!("whoami /user: {error}"))?;
        // "domain\user","S-1-5-21-…"
        let text = String::from_utf8_lossy(&output.stdout);
        text.trim()
            .rsplit(',')
            .next()
            .map(|field| field.trim().trim_matches('"').to_owned())
            .filter(|sid| output.status.success() && sid.starts_with("S-1-"))
            .ok_or_else(|| format!("whoami /user printed no security identifier: {text:?}"))
    })
    .as_deref()
    .map_err(Clone::clone)
}

/// Run `icacls` on `path` (spelled `\\?\…`, so long paths work too).
#[cfg(windows)]
fn icacls(path: &Path, arguments: &[String]) -> Result<(), String> {
    let mut spelled = path.as_os_str().to_string_lossy().replace('/', "\\");
    if !spelled.starts_with(r"\\") {
        spelled.insert_str(0, r"\\?\");
    }
    let output = std::process::Command::new("icacls")
        .arg(&spelled)
        .args(arguments)
        .stdin(std::process::Stdio::null())
        .output()
        .map_err(|error| format!("icacls {}: {error}", path.display()))?;
    if output.status.success() {
        Ok(())
    } else {
        Err(format!(
            "icacls {} {arguments:?}: {} {}",
            path.display(),
            String::from_utf8_lossy(&output.stdout).trim(),
            String::from_utf8_lossy(&output.stderr).trim()
        ))
    }
}

/// Take access to `path` away from this account, as a user meets a folder or a file
/// they may not open: mode 000 on Unix. On Windows, where the read-only attribute
/// cannot make anything unreadable, an explicit deny entry for this account on listing
/// a folder or reading a file's data and on writing or adding to it (`icacls /deny
/// <SID>:(RD,WD,AD)`), as mode 000 refuses both; the owner keeps the right to change
/// the entry, so [`allow_read`] and the run's restore give access back.
pub fn deny_read(path: &Path) -> Result<(), String> {
    #[cfg(unix)]
    {
        use std::os::unix::fs::PermissionsExt;
        fs::set_permissions(path, fs::Permissions::from_mode(0o000))
            .map_err(|error| format!("chmod 000 {}: {error}", path.display()))
    }
    #[cfg(windows)]
    {
        icacls(
            path,
            &["/deny".into(), format!("*{}:(RD,WD,AD)", account_sid()?)],
        )?;
        denied_entries().insert(path.to_path_buf());
        Ok(())
    }
}

/// Take away this account's right to change the folder `path`'s entries while it can
/// still list them: mode 0555 on Unix (no entry is created, removed or renamed in it;
/// the folder itself may still move). Windows, where a folder's read-only attribute
/// does not stop any of that, lets an entry go when either the entry or its folder
/// allows it, so there the folder gets a deny entry on adding files and folders and on
/// deleting its children (`(WD,AD,DC)`), and each of its present entries one on its own
/// deletion (`(DE)`).
#[cfg_attr(
    unix,
    expect(
        dead_code,
        reason = "only the Windows mode stand-in calls it; Unix scenarios chmod"
    )
)]
pub fn deny_write(path: &Path) -> Result<(), String> {
    #[cfg(unix)]
    {
        use std::os::unix::fs::PermissionsExt;
        fs::set_permissions(path, fs::Permissions::from_mode(0o555))
            .map_err(|error| format!("chmod 555 {}: {error}", path.display()))
    }
    #[cfg(windows)]
    {
        let sid = account_sid()?;
        for entry in fs::read_dir(path).map_err(|error| format!("{}: {error}", path.display()))? {
            let entry = entry
                .map_err(|error| format!("{}: {error}", path.display()))?
                .path();
            icacls(&entry, &["/deny".into(), format!("*{sid}:(DE)")])?;
            denied_entries().insert(entry);
        }
        icacls(path, &["/deny".into(), format!("*{sid}:(WD,AD,DC)")])?;
        denied_entries().insert(path.to_path_buf());
        Ok(())
    }
}

/// Whether this account may not create entries in the folder `path`, as
/// [`deny_write`] leaves it: no owner write bit on Unix, a refused probe on Windows.
#[cfg_attr(
    unix,
    expect(
        dead_code,
        reason = "only Windows checks call it; Unix scenarios read the mode"
    )
)]
pub fn write_protected(path: &Path) -> bool {
    let Ok(metadata) = fs::symlink_metadata(path) else {
        return false;
    };
    #[cfg(unix)]
    {
        use std::os::unix::fs::PermissionsExt;
        metadata.is_dir() && metadata.permissions().mode() & 0o200 == 0
    }
    #[cfg(not(unix))]
    write_denied(path, &metadata)
}

/// Give back what [`deny_read`] or [`deny_write`] took: mode 0755 (folders) or 0644
/// (files) on Unix; on Windows this account's deny entries removed from `path` and from
/// the entries of `path` that [`deny_write`] protected.
pub fn allow_read(path: &Path) -> Result<(), String> {
    #[cfg(unix)]
    {
        use std::os::unix::fs::PermissionsExt;
        let mode = if fs::symlink_metadata(path).is_ok_and(|metadata| metadata.is_dir()) {
            0o755
        } else {
            0o644
        };
        fs::set_permissions(path, fs::Permissions::from_mode(mode))
            .map_err(|error| format!("chmod {mode:o} {}: {error}", path.display()))
    }
    #[cfg(windows)]
    {
        let sid = account_sid()?;
        icacls(path, &["/remove:d".into(), format!("*{sid}")])?;
        let mut denied = denied_entries();
        denied.remove(path);
        let children: Vec<PathBuf> = denied
            .iter()
            .filter(|entry| entry.parent() == Some(path))
            .cloned()
            .collect();
        // A write-protected folder that the application moved (a Move keeps its mode)
        // holds entries that deny their own deletion under paths this process never
        // recorded: with none recorded here, the folder's entries on disk are cleared,
        // or the kept run folder could not be deleted.
        let unrecorded: Vec<PathBuf> = if children.is_empty()
            && fs::symlink_metadata(path).is_ok_and(|metadata| metadata.is_dir())
        {
            fs::read_dir(path)
                .into_iter()
                .flatten()
                .flatten()
                .map(|entry| entry.path())
                .collect()
        } else {
            Vec::new()
        };
        for child in children {
            if fs::symlink_metadata(&child).is_ok() {
                icacls(&child, &["/remove:d".into(), format!("*{sid}")])?;
            }
            denied.remove(&child);
        }
        drop(denied);
        for child in unrecorded {
            // Best effort: an entry without a deny entry of this account is unchanged.
            let _ = icacls(&child, &["/remove:d".into(), format!("*{sid}")]);
        }
        Ok(())
    }
}

/// Make the dot-named entry `path` hidden as the platform defines it: Unix hides a
/// dot-name by its name; Windows by the hidden attribute (`attrib +h`), which the
/// scenarios give their dot-names so that "hidden" means the same on both.
pub fn hide(path: &Path) -> Result<(), String> {
    #[cfg(windows)]
    {
        let output = std::process::Command::new("attrib")
            .arg("+h")
            .arg(path)
            .stdin(std::process::Stdio::null())
            .output()
            .map_err(|error| format!("attrib +h {}: {error}", path.display()))?;
        // attrib reports some failures on its output with a zero status.
        let text = String::from_utf8_lossy(&output.stdout);
        if !output.status.success() || !text.trim().is_empty() {
            return Err(format!("attrib +h {}: {}", path.display(), text.trim()));
        }
    }
    #[cfg(not(windows))]
    let _ = path;
    Ok(())
}

/// A directory junction at `link` to the folder `target`, the Windows directory link
/// that needs no privilege; the target need not exist. It is set natively
/// (`FSCTL_SET_REPARSE_POINT`, SECURITY.md), so no shell reads either path.
#[cfg(windows)]
pub fn junction(link: &Path, target: &Path) -> Result<(), String> {
    junction_windows::create(link, target).map_err(|error| {
        format!(
            "junction {} -> {}: {error}",
            link.display(),
            target.display()
        )
    })
}

/// A junction whose link and target names hold what a shell would expand or split
/// (`%PATH%`, `!PATH!` under delayed expansion, `^`, `&`) and a non-ASCII letter must
/// read back as exactly its target. Run in `folder` before the fixture is written.
#[cfg(windows)]
fn junction_self_test(folder: &Path) -> Result<(), String> {
    let check = create_fresh(folder, "junction-check")?;
    let target = check.join("target %PATH% !PATH! ^& ž");
    let link = check.join("link %PATH% !PATH! ^& ž");
    let result = junction(&link, &target).and_then(|()| {
        let read = fs::read_link(&link).map_err(|error| format!("{}: {error}", link.display()))?;
        if read == target {
            Ok(())
        } else {
            Err(format!(
                "junction self-test: {} reads back as {}, not {}",
                link.display(),
                read.display(),
                target.display()
            ))
        }
    });
    let removed =
        remove_tree(&check).map_err(|error| format!("cannot remove {}: {error}", check.display()));
    result.and(removed)
}

/// Entries below `path` (links not followed) that still block deleting it: folders
/// without owner read, write and search permission, files without owner write.
pub fn owner_locked(path: &Path) -> Vec<PathBuf> {
    let mut locked = Vec::new();
    locked_into(path, &mut locked);
    locked
}

fn locked_into(path: &Path, locked: &mut Vec<PathBuf>) {
    let Ok(metadata) = fs::symlink_metadata(path) else {
        return;
    };
    #[cfg(unix)]
    let blocked = {
        use std::os::unix::fs::PermissionsExt;
        let mode = metadata.permissions().mode();
        (metadata.is_dir() && mode & 0o700 != 0o700) || (metadata.is_file() && mode & 0o200 == 0)
    };
    #[cfg(not(unix))]
    let blocked = !metadata.file_type().is_symlink()
        && (metadata.permissions().readonly()
            || (metadata.is_dir() && read_denied(path, &metadata)));
    if blocked {
        locked.push(path.to_path_buf());
    }
    if metadata.is_dir() {
        for entry in fs::read_dir(path).into_iter().flatten().flatten() {
            locked_into(&entry.path(), locked);
        }
    }
}

/// Remove a tree that may contain read-only entries.
pub fn remove_tree(path: &Path) -> std::io::Result<()> {
    if !path.exists() {
        return Ok(());
    }
    make_writable(path);
    fs::remove_dir_all(path)
}

fn make_writable(path: &Path) {
    let Ok(metadata) = fs::symlink_metadata(path) else {
        return;
    };
    if metadata.file_type().is_symlink() {
        return;
    }
    #[cfg(unix)]
    {
        use std::os::unix::fs::PermissionsExt;
        let mode = metadata.permissions().mode() | 0o700;
        let _ = fs::set_permissions(path, fs::Permissions::from_mode(mode));
    }
    #[cfg(not(unix))]
    {
        let mut permissions = metadata.permissions();
        #[allow(clippy::permissions_set_readonly_false)]
        permissions.set_readonly(false);
        let _ = fs::set_permissions(path, permissions);
    }
    if metadata.is_dir() {
        for entry in fs::read_dir(path).into_iter().flatten().flatten() {
            make_writable(&entry.path());
        }
    }
}

/// Seed of the viewer scenarios' extra fixtures: their own sequence, so every file
/// generated before them stays byte-identical.
const VIEWER_SEED: u64 = SEED ^ 0x5649_4557;

impl Fixture {
    /// File pairs for the comparator and a grid of images for the thumbnail view.
    fn viewer_extras(&mut self) -> Result<(), String> {
        let mut random = Random::new(VIEWER_SEED);
        self.directory("compare", "file pairs for the comparator")?;
        let mut base = String::new();
        for line in 0..120 {
            base.push_str(&format!("{line:03} {}\n", sentence(&mut random, 6)));
        }
        self.write(
            "compare/same-a.txt",
            "text",
            "identical to same-b.txt",
            base.as_bytes(),
        )?;
        self.write(
            "compare/same-b.txt",
            "text",
            "identical to same-a.txt",
            base.as_bytes(),
        )?;
        // Three differences: line 10 changed, line 100 removed, a line inserted after 60.
        let mut lines: Vec<String> = base.lines().map(str::to_owned).collect();
        lines[10] = "010 this line differs in right.txt".to_owned();
        lines.remove(100);
        lines.insert(61, "inserted line only in right.txt".to_owned());
        let right = lines.join("\n") + "\n";
        self.write(
            "compare/left.txt",
            "text",
            "three differences from right.txt",
            base.as_bytes(),
        )?;
        self.write(
            "compare/right.txt",
            "text",
            "three differences from left.txt",
            right.as_bytes(),
        )?;
        // Large, but below the text comparator's 4 MiB per-file limit at every scale.
        let target = 3_584 << 10;
        let mut large = String::with_capacity(target + 128);
        let mut line = 0_u64;
        while large.len() < target {
            large.push_str(&format!("{line:08} {}\n", sentence(&mut random, 10)));
            line += 1;
        }
        let last = format!("\n{:08} ", line - 2);
        let changed = large
            .replacen("\n00000002 ", "\n00000002 CHANGED ", 1)
            .replacen(&last, &format!("{last}CHANGED "), 1);
        self.write(
            "compare/large-a.log",
            "text",
            "3.5 MiB log",
            large.as_bytes(),
        )?;
        self.write(
            "compare/large-b.log",
            "text",
            "large-a.log with lines 2 and N-2 changed",
            changed.as_bytes(),
        )?;
        // Over the comparator's limit: large-a.log with another 768 KiB appended.
        let mut over = large;
        while over.len() < (4_352 << 10) {
            over.push_str(&format!("{line:08} {}\n", sentence(&mut random, 10)));
            line += 1;
        }
        self.write(
            "compare/over-limit.log",
            "text",
            "4.25 MiB: over the 4 MiB text comparison limit",
            over.as_bytes(),
        )?;
        let mut utf16 = vec![0xFF, 0xFE];
        for unit in UNICODE_SAMPLE.encode_utf16() {
            utf16.extend_from_slice(&unit.to_le_bytes());
        }
        self.write(
            "compare/text-utf8.txt",
            "text",
            "multilingual sample as UTF-8",
            UNICODE_SAMPLE.as_bytes(),
        )?;
        self.write(
            "compare/text-utf16.txt",
            "text",
            "the same text as UTF-16 LE with BOM",
            &utf16,
        )?;
        let gradient = |x: u32, y: u32| [(x * 4) as u8, (y * 4) as u8, 128];
        self.write(
            "compare/image-a.png",
            "image",
            "64x64 gradient",
            &encode::png(64, 64, gradient),
        )?;
        self.write(
            "compare/image-b.png",
            "image",
            "image-a.png with a red 16x16 square",
            &encode::png(64, 64, |x, y| {
                if (16..32).contains(&x) && (16..32).contains(&y) {
                    [255, 0, 0]
                } else {
                    gradient(x, y)
                }
            }),
        )?;
        let binary = random.bytes(8192);
        let mut altered = binary.clone();
        for offset in [100, 4000, 8000] {
            altered[offset] ^= 0xFF;
        }
        self.write(
            "compare/binary-a.bin",
            "binary",
            "8192 random bytes",
            &binary,
        )?;
        self.write(
            "compare/binary-b.bin",
            "binary",
            "binary-a.bin with three bytes inverted",
            &altered,
        )?;

        self.directory("thumbs", "images for the thumbnail view")?;
        for index in 0..60_u32 {
            let colour = [
                (index * 37 % 256) as u8,
                (index * 91 % 256) as u8,
                ((index * 53 + 80) % 256) as u8,
            ];
            let path = self.root.join(format!("thumbs/tile-{index:02}.png"));
            let image = encode::png(96, 72, |x, y| {
                if x.abs_diff(y) < 4 {
                    [255, 255, 255]
                } else {
                    colour
                }
            });
            fs::write(&path, image).map_err(|error| format!("{}: {error}", path.display()))?;
        }
        self.record(
            "thumbs/tile-NN.png",
            "image",
            "60 PNGs of 96x72, one colour each with a white diagonal",
        );
        self.write(
            "thumbs/document.pdf",
            "pdf",
            "one page for a PDF preview",
            &encode::pdf(&["Thumbnail PDF fixture"]),
        )?;
        self.write(
            "thumbs/photo.jpg",
            "image",
            "128x64 greyscale JPEG",
            &encode::jpeg(16, 8, |bx, by| ((bx * 15 + by * 8) % 256) as u8),
        )?;
        Ok(())
    }
}
